%% --- 1. System Definition ---
clear; clc; close all;

s = tf('s');
G = 16 / (s^3 + 6*s^2 + 5*s + 8);

%% --- 2. Initial Stability Analysis ---
disp('--- Initial System Analysis ---'); %[output:537855f4]
T_initial = feedback(G, 1);
poles_initial = pole(T_initial);
disp('Initial closed-loop poles (should be in LHP):'); %[output:3645311f]
disp(poles_initial); %[output:9d18aaab]

figure; %[output:6916149b]
step(T_initial); %[output:6916149b]
title('Stable Closed-Loop Step Response (Original System)'); %[output:6916149b]
grid on; %[output:6916149b]

%% --- 3. Bode and Margin Calculation ---
disp('--- Calculating Stability Margins ---'); %[output:2bfcdd20]
[Gm, Pm, Wcg, Wcp] = margin(G);

fprintf('Gain Margin (Gm): %.3f (%.2f dB)\n', Gm, 20*log10(Gm)); %[output:270f5c78]
fprintf('Phase Margin (Pm): %.2f deg\n', Pm); %[output:42b10dc9]
fprintf('Gain Crossover Freq (Wcg): %.3f rad/s\n', Wcg); %[output:8bb1a47c]
fprintf('Phase Crossover Freq (Wcp): %.3f rad/s\n', Wcp); %[output:4d5fa2cd]

figure; %[output:0948c6ec]
margin(G); %[output:0948c6ec]
grid on; %[output:0948c6ec]
title('Bode Plot with Gain & Phase Margins'); %[output:0948c6ec]


PhaseMargin_deg = Pm;
theta_rad = PhaseMargin_deg * pi / 180;
T_delay = theta_rad / Wcp; % delay in seconds

s = tf('s');
Delay = exp(-T_delay * s);
G_lag = G * Delay;

margin(G_lag) %[output:996500a5]
%%

% Critical gain for phase margin = 0 (approx)
K_critical = Gm; 

%% 3. Closed-loop Systems at Critical Gain and Beyond
T_critical = feedback(K_critical * G, 1);
T_beyond = feedback(1.2 * K_critical * G, 1); % 20% higher gain, expected unstable

%% 4. Pole Analysis
poles_critical = pole(T_critical);
poles_beyond = pole(T_beyond);
disp('Closed-loop poles at critical gain:'); %[output:296342e0]
disp(poles_critical); %[output:84e36eae]
disp('Closed-loop poles at gain beyond critical (unstable expected):'); %[output:99213753]
disp(poles_beyond); %[output:0d7c6b90]

%% 5. Step Response Plots
figure; %[output:24d5d814]
step(T_critical); %[output:24d5d814]
title('Closed-Loop Step Response at Critical Gain (Phase Margin ~ 0)'); %[output:24d5d814]
grid on; %[output:24d5d814]

figure; %[output:49a136c7]
step(T_beyond); %[output:49a136c7]
title('Closed-Loop Step Response Beyond Critical Gain (Unstable)'); %[output:49a136c7]
grid on; %[output:49a136c7]

